// ---------------------------------------------------------------------------
// config - the only node you edit.
//
// Nothing in this workflow reads $env, so it behaves identically on self-hosted
// n8n and on n8n Cloud, needs no N8N_BLOCK_ENV_ACCESS_IN_NODE, and a threshold
// change costs a save rather than a host restart.
//
// The numbers agreed on the call live here, in one visible place - the
// threshold in the contract and the threshold in the workflow are the same
// threshold.
//
// Blank keys degrade instead of 401-ing:
//   INSTANTLY_API_KEY  blank -> the report goes out with the rates reported
//                               as missing rather than zero
//   LLM_API_KEY        blank -> the two-sentence prose is replaced by a
//                               computed opening
//   REPORT_WEBHOOK_URL blank -> falls back to ALERT_WEBHOOK_URL
//
// LEADS_SHEET_ID is the only required value - fill in your Google Sheet ID.
// ---------------------------------------------------------------------------

const LEADS_SHEET_ID = 'YOUR_GOOGLE_SHEET_ID';

const INSTANTLY_API_KEY = '';
const INSTANTLY_BASE_URL = 'https://api.instantly.ai';

const LLM_BASE_URL = 'https://llm.acme.example';
const LLM_API_KEY = '';
const LLM_MODEL = 'modelark/seed-2-0-pro-260328';
const LLM_MODEL_WRITER = 'modelark/seed-2-0-pro-260328';

// The brief's numbers. Everything in the report is measured against these.
const MONTHLY_TARGET = 14000;
const CALLS_TARGET = 20;

// The reply rate the 20-call target depends on. Put this in the SOW as a shared
// assumption - 14,000 sends does not guarantee 20 calls, 2% reply does.
const TARGET_REPLY_RATE = 2.0;

// Below this many sends in the week, rates are noise and the report says so
// instead of grading them.
const MIN_SAMPLE = 100;

// Thresholds that trigger a recommendation.
const BOUNCE_CEILING = 3.0;
const NOSHOW_CEILING = 30.0;

// Where the weekly report is posted. Falls back to ALERT_WEBHOOK_URL if unset.
const REPORT_WEBHOOK_URL = '';

// Where booking events and the daily calls desk get posted.
const ALERT_WEBHOOK_URL = '';

// ---------------------------------------------------------------------------
// derived - nothing below here needs editing
// ---------------------------------------------------------------------------

const leadsSheetId = String(LEADS_SHEET_ID || '').trim();
const instantlyApiKey = String(INSTANTLY_API_KEY || '').trim();
const llmApiKey = String(LLM_API_KEY || '').trim();
const reportWebhookUrl = String(REPORT_WEBHOOK_URL || '').trim();
const alertWebhookUrl = String(ALERT_WEBHOOK_URL || '').trim();
const llmModelWriter = String(LLM_MODEL_WRITER || '').trim() || String(LLM_MODEL || '').trim();

return [{
  json: {
    leads_sheet_id: leadsSheetId,

    instantly_api_key: instantlyApiKey,
    instantly_base_url: String(INSTANTLY_BASE_URL || 'https://api.instantly.ai').trim().replace(/\/+$/, ''),

    llm_base_url: String(LLM_BASE_URL || '').trim().replace(/\/+$/, ''),
    llm_api_key: llmApiKey,
    llm_model: String(LLM_MODEL || '').trim(),
    llm_model_writer: llmModelWriter,

    monthly_target: Number(MONTHLY_TARGET) || 14000,
    calls_target: Number(CALLS_TARGET) || 20,
    target_reply_rate: Number(TARGET_REPLY_RATE) || 2.0,
    min_sample: Number(MIN_SAMPLE) || 100,
    bounce_ceiling: Number(BOUNCE_CEILING) || 3.0,
    noshow_ceiling: Number(NOSHOW_CEILING) || 30.0,

    report_webhook_url: reportWebhookUrl || alertWebhookUrl,

    sheets_enabled: leadsSheetId !== '' && leadsSheetId !== 'YOUR_GOOGLE_SHEET_ID',
    instantly_enabled: instantlyApiKey !== '',
    llm_enabled: llmApiKey !== ''
  }
}];

// Everything the report asserts is computed here, deterministically, from three
// sources. The LLM downstream writes prose over these numbers and is never allowed to
// produce one of its own.
//
//   Bookings    (this template)  -> calls booked, held, no-showed, re-booked
//   SendLedger  (template 12)    -> what WE believe we sent, per subject variant
//   ESP         (Instantly)      -> what the ESP believes was sent, opened, replied, bounced
//
// Two send counts on purpose. When they diverge materially, something is wrong with the
// pipeline and that is worth more to the client than either number alone.

const num = (v) => { const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };
const pct = (a, b) => (b > 0 ? (a / b) * 100 : 0);
const r1 = (n) => Math.round(n * 10) / 10;

const MONTHLY_TARGET = num($('config').first().json.monthly_target) || 14000;
const CALLS_TARGET = num($('config').first().json.calls_target) || 20;
const TARGET_REPLY_RATE = num($('config').first().json.target_reply_rate) || 2.0;
const MIN_SAMPLE = num($('config').first().json.min_sample) || 100;
const BOUNCE_CEILING = num($('config').first().json.bounce_ceiling) || 3.0;
const NOSHOW_CEILING = num($('config').first().json.noshow_ceiling) || 30.0;

// The GCC working week is Sunday-Thursday. Every rate below is per working day, not per
// calendar day - dividing by 7 understates daily pace by 29% and makes a healthy week
// look behind.
const WORKING_DAYS_PER_WEEK = 5;
const WORKING_DAYS_PER_MONTH = 22;
const DAILY_TARGET = Math.round(MONTHLY_TARGET / WORKING_DAYS_PER_MONTH);
const WEEKLY_TARGET = DAILY_TARGET * WORKING_DAYS_PER_WEEK;

// Subject-variant floor. Singapore's Spam Control Act thresholds are per SUBJECT LINE,
// not per campaign, and the annual ceiling (10,000/yr) is the one that binds at this
// volume. Same arithmetic as template 12 - if the two ever disagree, 12 is the sender
// and wins.
const REQUIRED_VARIANTS = Math.ceil((MONTHLY_TARGET * 12) / 10000);

const now = new Date();
const weekEnd = new Date(now); weekEnd.setUTCHours(0, 0, 0, 0);
const weekStart = new Date(weekEnd.getTime() - 7 * 864e5);
const inWeek = (v) => { if (!v) return false; const d = new Date(v); return !isNaN(d) && d >= weekStart && d < weekEnd; };
const dayKey = (d) => d.toISOString().slice(0, 10);

// ---------------------------------------------------------------------------
// Source 1 - bookings. This is the deliverable the client actually bought.
// ---------------------------------------------------------------------------
let bookings = [];
try { bookings = $('[cred] Sheets - read bookings').all().map((i) => i.json).filter((b) => b && b.booking_id); } catch (e) { bookings = []; }

const weekBookings = bookings.filter((b) => inWeek(b.starts_at));
const booked = weekBookings.length;
const held = weekBookings.filter((b) => String(b.outcome || '').toLowerCase() === 'held').length;
const noShow = weekBookings.filter((b) => String(b.outcome || '').toLowerCase() === 'no_show').length;
const cancelled = weekBookings.filter((b) => String(b.stage || '').toLowerCase() === 'cancelled').length;
const rebookQueued = weekBookings.filter((b) => b.rebook_due).length;
// Anything in the past with no outcome is still open, not a success. The daily chain
// closes these out after NOSHOW_GRACE_HOURS; a pile-up here means that chain is not running.
const unmarked = weekBookings.filter((b) => new Date(b.starts_at) < now && !b.outcome).length;
const noShowRate = pct(noShow, held + noShow);

// ---------------------------------------------------------------------------
// Source 2 - our own send ledger, per subject variant.
// ---------------------------------------------------------------------------
let ledger = [];
try { ledger = $('[cred] Sheets - read send ledger').all().map((i) => i.json).filter((r) => r && r.subject_id); } catch (e) { ledger = []; }

const weekDayKeys = new Set();
for (let i = 0; i < 7; i++) weekDayKeys.add(dayKey(new Date(weekStart.getTime() + i * 864e5)));
// sent_today is a rolling counter stamped with day_key, so it only counts toward this
// week when its day_key falls inside the window.
const ledgerSends = ledger.reduce((sum, r) => sum + (weekDayKeys.has(String(r.day_key)) ? num(r.sent_today) : 0), 0);
const variantsInUse = new Set(ledger.filter((r) => num(r.sent_year) > 0).map((r) => String(r.subject_id))).size;

// Variants approaching a statutory ceiling. Reported before they bind, not after.
const variantsAtRisk = ledger
  .filter((r) => num(r.sent_year) >= 9000 * 0.85 || num(r.sent_month) >= 900 * 0.85)
  .map((r) => ({ subject: String(r.subject || r.subject_id), year: num(r.sent_year), month: num(r.sent_month) }));

// ---------------------------------------------------------------------------
// Source 3 - the ESP. Template 12 creates one campaign per sequence id, so a campaign
// row is a sequence row.
// ---------------------------------------------------------------------------
let espRows = [];
try {
  const raw = $('[cred] Instantly - campaign analytics').all().map((i) => i.json);
  for (const r of raw) {
    if (Array.isArray(r)) espRows.push(...r);
    else if (Array.isArray(r.items)) espRows.push(...r.items);
    else if (Array.isArray(r.data)) espRows.push(...r.data);
    else if (r && (r.campaign_name || r.campaign_id)) espRows.push(r);
  }
} catch (e) { espRows = []; }
const espReachable = espRows.length > 0;

const sequences = espRows.map((r) => {
  const sent = num(r.emails_sent_count ?? r.sent ?? r.total_sent);
  const opens = num(r.open_count ?? r.opened ?? r.unique_opens);
  const replies = num(r.reply_count ?? r.replied ?? r.total_replies);
  const bounces = num(r.bounced_count ?? r.bounced ?? r.total_bounces);
  return {
    sequence: String(r.campaign_name || r.campaign_id || 'unnamed'),
    sent, opens, replies, bounces,
    open_rate: r1(pct(opens, sent)),
    reply_rate: r1(pct(replies, sent)),
    bounce_rate: r1(pct(bounces, sent)),
    graded: sent >= MIN_SAMPLE,
  };
}).sort((a, b) => b.reply_rate - a.reply_rate);

const espSends = sequences.reduce((s, x) => s + x.sent, 0);
const replies = sequences.reduce((s, x) => s + x.replies, 0);
const opens = sequences.reduce((s, x) => s + x.opens, 0);
const bounces = sequences.reduce((s, x) => s + x.bounces, 0);

// The ESP is authoritative for sends when reachable - it is the thing that actually
// handed the message to a mail server. The ledger is our intent.
const sent = espReachable ? espSends : ledgerSends;
const replyRate = r1(pct(replies, sent));
const openRate = r1(pct(opens, sent));
const bounceRate = r1(pct(bounces, sent));

// Divergence between intent and delivery. Under 5% is timing at the window edges.
const sendGap = ledgerSends > 0 && espReachable
  ? r1((Math.abs(espSends - ledgerSends) / Math.max(espSends, ledgerSends)) * 100)
  : 0;

// ---------------------------------------------------------------------------
// Pace. The month-to-date view, because the deliverable is monthly.
// ---------------------------------------------------------------------------
const monthStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
let workingDaysElapsed = 0;
for (let d = new Date(monthStart); d <= now; d = new Date(d.getTime() + 864e5)) {
  const wd = d.getUTCDay();
  if (wd >= 0 && wd <= 4) workingDaysElapsed++; // Sun(0) .. Thu(4)
}
const monthBookings = bookings.filter((b) => { const d = new Date(b.starts_at); return !isNaN(d) && d >= monthStart && d <= now; }).length;
const callsPaceTarget = Math.round((CALLS_TARGET / WORKING_DAYS_PER_MONTH) * workingDaysElapsed);
const sendPaceTarget = DAILY_TARGET * workingDaysElapsed;

// ---------------------------------------------------------------------------
// Recommendations. Rule-derived, ordered by what would cost the most to ignore.
// Each carries the number that triggered it so the client can check the reasoning.
// ---------------------------------------------------------------------------
const recs = [];
const tooEarly = sent < MIN_SAMPLE;

if (tooEarly) {
  recs.push(`Too early to grade: ${sent} sends this week is under the ${MIN_SAMPLE} sample floor. Rates below are noise - read them next week.`);
}

if (!espReachable) {
  recs.push('ESP analytics did not return. Open, reply and bounce rates are missing, not zero - send volume below is our own ledger. Check the API key before reading anything into this report.');
}

if (!tooEarly && espReachable && bounceRate > BOUNCE_CEILING) {
  const worst = sequences.filter((s) => s.graded).sort((a, b) => b.bounce_rate - a.bounce_rate)[0];
  recs.push(`Bounce rate ${bounceRate}% is over the ${BOUNCE_CEILING}% ceiling${worst ? ` (worst: ${worst.sequence} at ${worst.bounce_rate}%)` : ''}. Stop scaling and re-verify the list before the next batch - bounces burn domain reputation for every sequence, not just this one.`);
}

if (!tooEarly && espReachable && replyRate < TARGET_REPLY_RATE) {
  const severity = replyRate < TARGET_REPLY_RATE / 2 ? 'far under' : 'under';
  recs.push(`Reply rate ${replyRate}% is ${severity} the ${TARGET_REPLY_RATE}% the ${CALLS_TARGET}-call target depends on. The fix is targeting and copy, not volume - at this rate ${MONTHLY_TARGET.toLocaleString()} sends/month lands around ${Math.round(sent > 0 ? (MONTHLY_TARGET * replyRate / 100) * 0.25 * 0.30 : 0)} calls, not ${CALLS_TARGET}.`);
}

if (!tooEarly && espReachable && replyRate >= TARGET_REPLY_RATE) {
  recs.push(`Reply rate ${replyRate}% is at or above the ${TARGET_REPLY_RATE}% assumption. Volume is the lever this month, not copy.`);
}

const graded = sequences.filter((s) => s.graded);
if (graded.length >= 2) {
  const best = graded[0];
  const worst = graded[graded.length - 1];
  if (worst.reply_rate < best.reply_rate / 2) {
    recs.push(`Retire or rewrite '${worst.sequence}' - ${worst.reply_rate}% reply against ${best.reply_rate}% on '${best.sequence}' over ${worst.sent} sends. Moving its volume to the winning angle is the cheapest gain available this week.`);
  }
}

if (held + noShow >= 3 && noShowRate > NOSHOW_CEILING) {
  recs.push(`No-show rate ${r1(noShowRate)}% is over the ${NOSHOW_CEILING}% ceiling. Cold-email bookings decay with distance from the reply - shorten the booking-to-call gap before adding leads to the top.`);
}

if (unmarked > 0) {
  recs.push(`${unmarked} past booking${unmarked === 1 ? '' : 's'} still unmarked. The daily 07:00 chain closes these out - if they are piling up, that workflow is not running.`);
}

if (variantsInUse > 0 && variantsInUse < REQUIRED_VARIANTS) {
  recs.push(`COMPLIANCE: ${variantsInUse} subject variants in rotation, ${REQUIRED_VARIANTS} needed at ${MONTHLY_TARGET.toLocaleString()}/month. Singapore's thresholds are per subject line and the annual ceiling binds first. Add variants before raising volume.`);
}
for (const v of variantsAtRisk) {
  recs.push(`COMPLIANCE: subject '${v.subject}' is at ${v.year}/yr and ${v.month}/30d, inside 15% of its ceiling. Rotate it out now rather than when it blocks.`);
}

if (sendGap > 5) {
  recs.push(`Our ledger says ${ledgerSends.toLocaleString()} sends, the ESP says ${espSends.toLocaleString()} - ${sendGap}% apart. Reconcile before quoting either number to the client.`);
}

if (monthBookings < callsPaceTarget) {
  recs.push(`Behind on calls: ${monthBookings} booked against ${callsPaceTarget} expected by working day ${workingDaysElapsed}. Monthly target is ${CALLS_TARGET}.`);
} else {
  recs.push(`On pace for calls: ${monthBookings} booked against ${callsPaceTarget} expected by working day ${workingDaysElapsed}.`);
}

if (!recs.length) recs.push('No exceptions this week. Everything is inside its threshold.');

// ---------------------------------------------------------------------------
// Report text.
// ---------------------------------------------------------------------------
const range = `${dayKey(weekStart)} to ${dayKey(new Date(weekEnd.getTime() - 864e5))}`;
const na = (v, suffix) => (espReachable && !tooEarly ? `${v}${suffix}` : 'n/a');

const lines = [];
lines.push(`Weekly performance - ${range}`);
lines.push('');
lines.push('CALLS  (the deliverable)');
lines.push(`  Booked this week       ${booked}`);
lines.push(`  Held                   ${held}`);
lines.push(`  No-showed              ${noShow}${held + noShow > 0 ? `  (${r1(noShowRate)}%)` : ''}`);
lines.push(`  Cancelled              ${cancelled}`);
lines.push(`  Re-books queued        ${rebookQueued}`);
lines.push(`  Month to date          ${monthBookings} of ${CALLS_TARGET}   (pace: ${callsPaceTarget} by working day ${workingDaysElapsed})`);
lines.push('');
lines.push('SENDING');
lines.push(`  Sent this week         ${sent.toLocaleString()} of ${WEEKLY_TARGET.toLocaleString()} target`);
lines.push(`  Pace target to date    ${sendPaceTarget.toLocaleString()}  (working day ${workingDaysElapsed} of ${WORKING_DAYS_PER_MONTH})`);
lines.push(`  Reply rate             ${na(replyRate, '%')}   (target ${TARGET_REPLY_RATE}%)`);
lines.push(`  Bounce rate            ${na(bounceRate, '%')}   (ceiling ${BOUNCE_CEILING}%)`);
lines.push(`  Open rate              ${na(openRate, '%')}   - see note`);
lines.push('');
if (sequences.length) {
  lines.push('BY SEQUENCE');
  for (const s of sequences) {
    const tag = s.graded ? '' : '  (under sample)';
    lines.push(`  ${s.sequence.padEnd(22).slice(0, 22)} ${String(s.sent).padStart(6)} sent   ${String(s.reply_rate).padStart(5)}% reply   ${String(s.bounce_rate).padStart(5)}% bounce${tag}`);
  }
  lines.push('');
}
lines.push('RECOMMENDATIONS');
for (const r of recs) lines.push(`  - ${r}`);
lines.push('');
lines.push('Note on open rate: Apple Mail Privacy Protection pre-fetches images for a large');
lines.push('share of recipients, so opens are inflated by a proxy server rather than a person.');
lines.push('It is reported because it was asked for. Reply rate and calls booked are the two');
lines.push('numbers that move with anything we actually control.');

return [{
  json: {
    week_start: dayKey(weekStart),
    week_end: dayKey(new Date(weekEnd.getTime() - 864e5)),
    range,
    booked, held, no_show: noShow, cancelled, rebook_queued: rebookQueued, unmarked,
    no_show_rate: r1(noShowRate),
    month_bookings: monthBookings, calls_target: CALLS_TARGET, calls_pace_target: callsPaceTarget,
    sent, ledger_sends: ledgerSends, esp_sends: espSends, send_gap_pct: sendGap,
    replies, opens, bounces,
    reply_rate: replyRate, open_rate: openRate, bounce_rate: bounceRate,
    weekly_send_target: WEEKLY_TARGET, working_days_elapsed: workingDaysElapsed,
    variants_in_use: variantsInUse, variants_required: REQUIRED_VARIANTS,
    esp_reachable: espReachable, too_early: tooEarly, min_sample: MIN_SAMPLE,
    sequences, recommendations: recs,
    text: lines.join('\n'),
  },
}];

// The report must go out with or without the model. A week with no report reads as a
// week with nothing to report, which is the opposite of true when the model call is what
// failed. Same fallback pattern as the booking confirmation in the main workflow.
const report = $('compute the week').first().json;

let summary = '';
try {
  summary = String($json?.choices?.[0]?.message?.content || '').trim();
} catch (e) {
  summary = '';
}

// Guard against the model inventing a figure. If it emits a number that is not one of
// ours, drop the prose entirely rather than shipping a plausible wrong number to a
// client - a fabricated metric in a performance report is unrecoverable.
if (summary) {
  const known = new Set([
    report.booked, report.month_bookings, report.calls_target, report.calls_pace_target,
    report.no_show_rate, report.sent, report.weekly_send_target, report.reply_rate,
    report.bounce_rate, report.open_rate, report.held, report.no_show,
  ].map((n) => String(n)));
  const emitted = summary.match(/\d+(?:\.\d+)?/g) || [];
  const invented = emitted.filter((n) => !known.has(n) && !known.has(String(Number(n))));
  if (invented.length) {
    summary = '';
    report.summary_dropped = `model emitted ${invented.length} figure(s) not in the input: ${invented.join(', ')}`;
  }
}

const headline = summary
  || `${report.booked} call${report.booked === 1 ? '' : 's'} booked this week, ${report.month_bookings} month to date against a target of ${report.calls_target}. ${report.recommendations[0]}`;

report.summary = headline;
report.summary_source = summary ? 'model' : 'computed';
report.text = `${headline}\n\n${report.text}`;

return [{ json: report }];
